import{z as s,x as d,o,c as n,q as t,j as i,D as l,d as E,s as B,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"溢出与重物化","description":"","frontmatter":{"title":"溢出与重物化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/spill-remat.md","filePath":"cs/spill-remat.md","lastUpdated":1791063341000}'),p={name:"cs/spill-remat.md"};function c(C,a,D,m,h,u){const r=d("Mermaid");return o(),n("div",null,[a[2]||(a[2]=t('<h1 id="溢出与重物化" tabindex="-1">溢出与重物化 <a class="header-anchor" href="#溢出与重物化" aria-label="Permalink to &quot;溢出与重物化&quot;">​</a></h1><div class="epigraph"><p>颜色不够就把虚拟寄存器存到栈槽；能从立即数或不变地址再算出来的值，宁可重物化，也不占一条活过调用的槽。</p><footer>—— 据 Chaitin, Register Allocation and Spilling, 1982；Briggs, Cooper and Torczon, Rematerialization, 1992 整理</footer></div><p>上一课<a href="/cs/regalloc-color">寄存器分配着色</a>建冲突图、启发式 \\(K\\)-着色，失败则溢出再写 IR。本课不重做简化压栈。缺口是<strong>溢出之后写什么指令</strong>：<code>store</code>/<code>load</code> 到帧槽，以及 Briggs 的重物化——常量、全局地址、<code>sp</code> 相对的不变计算不必 round-trip 内存。窥孔下一课再清 <code>move</code> 垃圾。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>着色挑出溢出候选（度数高、跨度长、在循环外代价低）。朴素：在每次使用前 load、定值后 store。槽位按帧布局编号，<a href="/cs/calling-convention-stack">调用约定</a> 的帧指针已有直觉，ABI 课再钉对齐。缺口是代价：load 延迟与占用，可能让调度与活跃一起变坏，故分配–溢出–再着色循环。</p><p>重物化：若值的定义是 <code>li t, 4</code> 或 <code>lui+addi</code> 形成的池常量，使用处重新执行那几条便宜指令，不分配槽、不延长内存相关。判断：定义无副作用、操作数随时可再得（立即数、日历寄存器）。循环里重物化 vs 在循环外 load 一次，用简单代价比。</p><h3 id="溢出不是-malloc" tabindex="-1">溢出不是 malloc <a class="header-anchor" href="#溢出不是-malloc" aria-label="Permalink to &quot;溢出不是 malloc&quot;">​</a></h3><p>槽在当前帧，随调用生灭。不要把 spill 写成堆对象。callee-save 的保存也是一种「溢出到序言」，但是 ABI 合同，不是着色失败。</p><p><span class="marginnote">Chaitin 1982 溢出。Briggs et al. 1992（PLDI）rematerialization。乐观着色减少「其实着得上却被溢出」的候选。本课两者都要。</span></p><p><span class="marginnote">术语翻译：spill 就是把编译器虚拟出来放不下的寄存器值，在每次用到前从栈槽 load 回来、改完再 store 存回去——相当于图书馆借不到阅览位，把书先放回书架。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对溢出名：拆活跃区间或整名溢出。插入访问。对可重物化名：在使用处复制定义指令，删原跨区间的冲突边。更新 IR 后重算活跃与冲突图，再着色。</p>',12)),(o(),i(A,null,{default:l(()=>[B(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAIL%5B%22%E7%9D%80%E8%89%B2%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20COST%5B%22%E9%80%89%E6%BA%A2%E5%87%BA%E5%90%8D%22%5D%0A%20%20COST%20--%3E%20MEM%5B%22store%2Fload%20%E6%A7%BD%22%5D%0A%20%20COST%20--%3E%20REM%5B%22%E9%87%8D%E7%89%A9%E5%8C%96%E5%BB%89%E4%BB%B7%E5%AE%9A%E4%B9%89%22%5D%0A%20%20MEM%20--%3E%20RE%5B%22%E5%86%8D%E7%9D%80%E8%89%B2%22%5D%0A%20%20REM%20--%3E%20RE%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"无限循环：每次必须减少「无法着色的压力」，或放大 \\(K\\) 的有效（拆区间）。实现设轮数上限。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[E("溢出增加访存，"),e("a",{href:"/cs/locality-principle"},"Cache"),E(" 变差，分配器不模拟层次。重物化增加指令条数、可能加长调度关键路径，用加法延迟对比 load 延迟。φ 应在溢出前拆掉，否则槽与前驱 "),e("code",null,"move"),E(" 纠缠。")],-1)),(o(),i(A,null,{default:l(()=>[B(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E6%9F%90%E4%B8%AA%E5%80%BC%E5%BF%85%E9%A1%BB%E7%A6%BB%E5%BC%80%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%20--%3E%20Q1%7B%22%E5%AE%9A%E4%B9%89%E6%97%A0%E5%89%AF%E4%BD%9C%E7%94%A8%EF%BC%9F%22%7D%0A%20%20Q1%20--%3E%7C%22%E5%90%A6%22%7C%20S1%5B%22%E5%8F%AA%E8%83%BD%E6%BA%A2%E5%87%BA%E5%88%B0%E6%A7%BD%22%5D%0A%20%20Q1%20--%3E%7C%22%E6%98%AF%22%7C%20Q2%7B%22%E6%93%8D%E4%BD%9C%E6%95%B0%E9%9A%8F%E6%97%B6%E5%8F%AF%E5%BE%97%EF%BC%9F%EF%BC%9Cbr%2F%EF%BC%9E%E7%AB%8B%E5%8D%B3%E6%95%B0%20%2F%20%E4%B8%8D%E5%8F%98%E5%9C%B0%E5%9D%80%22%7D%0A%20%20Q2%20--%3E%7C%22%E5%90%A6%22%7C%20S2%5B%22%E6%BA%A2%E5%87%BA%E5%88%B0%E6%A7%BD%22%5D%0A%20%20Q2%20--%3E%7C%22%E6%98%AF%22%7C%20Q3%7B%22%E4%BD%BF%E7%94%A8%E7%82%B9%E5%9C%A8%E5%BE%AA%E7%8E%AF%E9%87%8C%EF%BC%9F%22%7D%0A%20%20Q3%20--%3E%7C%22%E5%BE%AA%E7%8E%AF%E5%A4%96%20load%20%E6%9B%B4%E7%9C%81%22%7C%20S3%5B%22%E5%BE%AA%E7%8E%AF%E5%A4%96%20load%20%E4%B8%80%E6%AC%A1%20%2B%20%E6%A7%BD%22%5D%0A%20%20Q3%20--%3E%7C%22%E5%AE%9A%E4%B9%89%E5%8F%AA%E8%A6%81%E5%87%A0%E6%9D%A1%E4%BE%BF%E5%AE%9C%E6%8C%87%E4%BB%A4%22%7C%20R%5B%22%E5%9C%A8%E4%BD%BF%E7%94%A8%E5%A4%84%E9%87%8D%E7%89%A9%E5%8C%96%22%5D%0A%20%20R%20--%3E%20RC%5B%22%E5%88%A0%E5%86%B2%E7%AA%81%E8%BE%B9%EF%BC%8C%E9%87%8D%E7%AE%97%E5%86%8D%E7%9D%80%E8%89%B2%22%5D%0A%20%20S1%20--%3E%20RC2%5B%22%E9%87%8D%E7%AE%97%E6%B4%BB%E8%B7%83%E4%B8%8E%E5%86%B2%E7%AA%81%E5%9B%BE%E5%86%8D%E7%9D%80%E8%89%B2%22%5D%0A%20%20S2%20--%3E%20RC2%0A%20%20S3%20--%3E%20RC2%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p>不要溢出 <code>sp</code> 本身。不要把条件执行的定值重物化到必经路上而不顾控制。</p><p><span class="marginnote">数字实例：RISC 上 <code>li t, 4</code> 是 1 条指令约 1 个周期，而槽访问是 1 次 store + 1 次 load；若 load 命中 L1 按 4 周期算，一次 round-trip 约 5+ 周期——循环跑 1000 次就是约 5000 周期 vs 1000 周期，差 5 倍。</span></p><p><span class="marginnote">常见误区：初学者容易以为重物化「免费」。实际上它把定义指令复制到每个使用点，指令条数变多、可能拉长调度关键路径；定义一旦有副作用（如带标志位的除法），复制还会改变语义，这时只能老老实实溢出到槽。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写窥孔模式、不输出目标文件。后课默认：函数体是物理寄存器加必要的 spill/re-mat。短窗口代数简化是窥孔的缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>溢出：帧槽 round-trip；重物化：再执行廉价定义。</li><li>二者都改变 IR，需再着色。</li><li>槽不是堆；合同保存不是失败溢出。</li><li>出处：Chaitin, 1982；Briggs, Cooper and Torczon, 1992。</li></ul>',7))])}const g=s(p,[["render",c]]);export{f as __pageData,g as default};
